import { NextRequest } from "next/server";
import { eq, sql } from "drizzle-orm";
import { db, schema } from "@/app/lib/db";
import { newGrabCode, newId } from "@/app/lib/codes";
import { getOwnerCookie } from "@/app/lib/identity";
import { shortenUrl } from "@/app/lib/shorten";

function originFor(request: NextRequest): string {
  const envOrigin = process.env.PUBLIC_ORIGIN;
  if (envOrigin) return envOrigin.replace(/\/$/, "");
  const host = request.headers.get("host");
  const proto =
    request.headers.get("x-forwarded-proto") ??
    (request.url.startsWith("https") ? "https" : "http");
  return `${proto}://${host}`;
}

function normalizeDestination(raw: string): string | null {
  const trimmed = raw.trim();
  if (!trimmed) return null;
  const withProto = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
  try {
    const u = new URL(withProto);
    if (u.protocol !== "http:" && u.protocol !== "https:") return null;
    return u.toString();
  } catch {
    return null;
  }
}

export async function POST(request: NextRequest) {
  const owner = await getOwnerCookie();
  if (!owner) {
    return Response.json({ error: "Missing identity cookie." }, { status: 400 });
  }

  let payload: { destinationUrl?: string; label?: string };
  try {
    payload = await request.json();
  } catch {
    return Response.json({ error: "Invalid JSON body." }, { status: 400 });
  }

  const destination = normalizeDestination(payload.destinationUrl ?? "");
  if (!destination) {
    return Response.json(
      { error: "destinationUrl must be a valid http(s) URL." },
      { status: 400 }
    );
  }

  const code = newGrabCode();
  const id = newId();
  const origin = originFor(request);
  const fullUrl = `${origin}/g/${code}`;
  const shortUrl = await shortenUrl(fullUrl);

  await db.insert(schema.grabs).values({
    id,
    code,
    ownerCookie: owner,
    destinationUrl: destination,
    label: payload.label?.trim() || null,
    shortUrl: shortUrl,
    createdAt: Math.floor(Date.now() / 1000),
  });

  return Response.json({ id, code, fullUrl, shortUrl });
}

export async function GET() {
  const owner = await getOwnerCookie();
  if (!owner) return Response.json({ grabs: [] });

  const rows = await db
    .select({
      id: schema.grabs.id,
      code: schema.grabs.code,
      destinationUrl: schema.grabs.destinationUrl,
      label: schema.grabs.label,
      shortUrl: schema.grabs.shortUrl,
      createdAt: schema.grabs.createdAt,
      clickCount: sql<number>`COUNT(${schema.clicks.id})`
        .mapWith(Number)
        .as("click_count"),
    })
    .from(schema.grabs)
    .leftJoin(schema.clicks, eq(schema.clicks.grabId, schema.grabs.id))
    .where(eq(schema.grabs.ownerCookie, owner))
    .groupBy(schema.grabs.id)
    .orderBy(sql`${schema.grabs.createdAt} DESC`);

  return Response.json({ grabs: rows });
}

import { NextRequest } from "next/server";
import type { IPstackResponse, LookupResult } from "@/app/lib/ipstack";

const IPSTACK_BASE = "http://api.ipstack.com";

const isPrivate = (ip: string) =>
  ip === "::1" ||
  ip === "127.0.0.1" ||
  ip.startsWith("10.") ||
  ip.startsWith("192.168.") ||
  /^172\.(1[6-9]|2\d|3[01])\./.test(ip) ||
  ip.startsWith("fc") ||
  ip.startsWith("fd");

const isValidIp = (ip: string) => {
  const v4 = /^(\d{1,3}\.){3}\d{1,3}$/;
  const v6 = /^[0-9a-fA-F:]+$/;
  return v4.test(ip) || (v6.test(ip) && ip.includes(":"));
};

const maskKey = (url: string) =>
  url.replace(/access_key=[^&]+/i, "access_key=••••••••");

export async function GET(request: NextRequest) {
  const key = process.env.IPSTACK_ACCESS_KEY;
  if (!key || key === "PASTE_YOUR_NEW_IPSTACK_KEY_HERE") {
    return Response.json(
      {
        error:
          "IPSTACK_ACCESS_KEY is not set. Add it to .env.local and restart the dev server.",
      },
      { status: 500 }
    );
  }

  const url = new URL(request.url);
  const ipParam = url.searchParams.get("ip")?.trim();

  let target: string;
  if (ipParam) {
    if (!isValidIp(ipParam)) {
      return Response.json(
        { error: `"${ipParam}" is not a valid IPv4 or IPv6 address.` },
        { status: 400 }
      );
    }
    target = ipParam;
  } else {
    const xff = request.headers.get("x-forwarded-for");
    const candidate = xff?.split(",")[0]?.trim() ?? "";
    target = candidate && !isPrivate(candidate) ? candidate : "check";
  }

  const endpoint =
    target === "check"
      ? `${IPSTACK_BASE}/check?access_key=${key}&hostname=1&security=1`
      : `${IPSTACK_BASE}/${encodeURIComponent(target)}?access_key=${key}&hostname=1&security=1`;

  const started = Date.now();
  let upstream: Response;
  try {
    upstream = await fetch(endpoint, { cache: "no-store" });
  } catch (e) {
    return Response.json(
      {
        error: `Failed to reach IPstack: ${e instanceof Error ? e.message : String(e)}`,
      },
      { status: 502 }
    );
  }
  const elapsedMs = Date.now() - started;
  const body = (await upstream.json()) as IPstackResponse;

  const result: LookupResult = {
    request: { url: maskKey(endpoint), method: "GET" },
    response: { status: upstream.status, elapsedMs, body },
    target,
  };

  return Response.json(result);
}

import type { NextRequest } from "next/server";
import { and, asc, eq } from "drizzle-orm";
import { db, schema } from "@/app/lib/db";
import { getOwnerCookie } from "@/app/lib/identity";

export async function GET(
  _request: NextRequest,
  ctx: RouteContext<"/api/grabs/[code]">
) {
  const { code } = await ctx.params;
  const owner = await getOwnerCookie();
  if (!owner) return Response.json({ error: "unauthorized" }, { status: 401 });

  const [grab] = await db
    .select()
    .from(schema.grabs)
    .where(
      and(eq(schema.grabs.code, code), eq(schema.grabs.ownerCookie, owner))
    )
    .limit(1);
  if (!grab) return Response.json({ error: "not found" }, { status: 404 });

  const rows = await db
    .select()
    .from(schema.clicks)
    .where(eq(schema.clicks.grabId, grab.id))
    .orderBy(asc(schema.clicks.capturedAt));

  const clicks = rows.map((r) => ({
    ...r,
    continued: Boolean(r.continued),
    ipstack: r.ipstackJson ? safeParse(r.ipstackJson) : null,
  }));

  return Response.json({ grab, clicks });
}

function safeParse(s: string): unknown {
  try {
    return JSON.parse(s);
  } catch {
    return null;
  }
}

import type { NextRequest } from "next/server";
import { eq } from "drizzle-orm";
import { db, schema } from "@/app/lib/db";

export async function GET(
  _request: NextRequest,
  ctx: RouteContext<"/api/clicks/[id]/continue">
) {
  const { id } = await ctx.params;

  const [click] = await db
    .select()
    .from(schema.clicks)
    .where(eq(schema.clicks.id, id))
    .limit(1);
  if (!click) return new Response("Click not found", { status: 404 });

  const [grab] = await db
    .select()
    .from(schema.grabs)
    .where(eq(schema.grabs.id, click.grabId))
    .limit(1);
  if (!grab) return new Response("Grab not found", { status: 404 });

  await db
    .update(schema.clicks)
    .set({ continued: 1 })
    .where(eq(schema.clicks.id, id));

  return Response.redirect(grab.destinationUrl, 302);
}

import { NextResponse, type NextRequest } from "next/server";

// Next.js 16 renamed Middleware to Proxy. This file runs before every request
// (excluding the matcher exclusions below) and sets a persistent cookie UUID
// so we can scope "your grabs" to the creator's browser without auth.
export function proxy(request: NextRequest) {
  const res = NextResponse.next();
  if (!request.cookies.get("ipwiz_id")) {
    const id = crypto.randomUUID();
    res.cookies.set("ipwiz_id", id, {
      httpOnly: true,
      sameSite: "lax",
      path: "/",
      maxAge: 60 * 60 * 24 * 365 * 2,
    });
  }
  return res;
}

